import json
import os

def _token():
    token = os.environ.get("SEED_TOKEN")
    if token:
        return token
    with open(".env") as f:
        for line in f:
            if line.startswith("SEED_TOKEN="):
                return line.strip().split("=", 1)[1]
    raise SystemExit("no SEED_TOKEN")

def run():
    os.makedirs("seed", exist_ok=True)
    with open("seed/manifest.json", "w") as f:
        json.dump({"token": _token()}, f)

if __name__ == "__main__":
    run()
    print("seed: ok")

